use anyhow::Result;
use clap::Parser;
use crossterm::{
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{CrosstermBackend, Backend},
    Terminal,
    Frame,
    layout::{Layout, Constraint, Direction},
    widgets::{Block, Borders, Paragraph, Wrap},
    text::{Text, Line, Span},
};
use std::io::{self, Read, Write};
use std::path::PathBuf;
use std::process::Command;
use std::fs;
use dirs::config_dir;

#[derive(Parser, Debug)]
#[command(name = "pipr")]
#[command(about = "A commandline utility by Leon Kowarschick", long_about = None)]
struct Args {
    #[arg(short, long, help = "text inserted into the textfield on startup")]
    default: Option<String>,

    #[arg(short, long, help = "write final command to file")]
    out_file: Option<PathBuf>,

    #[arg(long, help = "read initial command from file")]
    in_file: Option<PathBuf>,

    #[arg(long, help = "print out the default configuration file")]
    config_reference: bool,

    #[arg(short, long, help = "keep linebreaks in finished command when closing")]
    raw_mode: bool,

    #[arg(long, help = "disable isolation. This will run the commands directly on your system, without protection. Take care.")]
    no_isolation: bool,
}

struct AppState {
    command_input: String,
    output: String,
    cursor_pos: usize,
    history: Vec<String>,
    history_index: usize,
    show_help: bool,
    autoeval: bool,
    show_history: bool,
    bookmarks: Vec<String>,
    paranoid_history: bool,
    no_isolation: bool,
}

impl AppState {
    fn new(no_isolation: bool) -> Self {
        Self {
            command_input: String::new(),
            output: String::new(),
            cursor_pos: 0,
            history: load_history().unwrap_or_default(),
            history_index: 0,
            show_help: false,
            autoeval: true,
            show_history: false,
            bookmarks: Vec::new(),
            paranoid_history: false,
            no_isolation,
        }
    }

    fn execute_command(&mut self) {
        let cmd = self.command_input.trim();
        if cmd.is_empty() {
            return;
        }

        let output = if self.no_isolation {
            execute_direct(cmd)
        } else {
            execute_with_isolation(cmd)
        };

        self.output = output;
        self.history.push(cmd.to_string());
        save_history(&self.history).ok();
    }

    fn handle_char(&mut self, c: char) {
        self.command_input.insert(self.cursor_pos, c);
        self.cursor_pos += 1;
        if self.autoeval {
            self.execute_command();
        }
    }

    fn backspace(&mut self) {
        if self.cursor_pos > 0 {
            self.cursor_pos -= 1;
            self.command_input.remove(self.cursor_pos);
            if self.autoeval {
                self.execute_command();
            }
        }
    }

    fn prev_history(&mut self) {
        if self.history_index < self.history.len() {
            self.history_index += 1;
            if let Some(cmd) = self.history.get(self.history.len() - self.history_index) {
                self.command_input = cmd.clone();
                self.cursor_pos = self.command_input.len();
                if self.autoeval {
                    self.execute_command();
                }
            }
        }
    }

    fn next_history(&mut self) {
        if self.history_index > 1 {
            self.history_index -= 1;
            if let Some(cmd) = self.history.get(self.history.len() - self.history_index) {
                self.command_input = cmd.clone();
                self.cursor_pos = self.command_input.len();
                if self.autoeval {
                    self.execute_command();
                }
            }
        } else if self.history_index == 1 {
            self.history_index = 0;
            self.command_input.clear();
            self.cursor_pos = 0;
        }
    }
}

fn execute_direct(cmd: &str) -> String {
    match Command::new("bash").arg("-c").arg(cmd).output() {
        Ok(output) => {
            let stdout = String::from_utf8_lossy(&output.stdout);
            let stderr = String::from_utf8_lossy(&output.stderr);
            if stderr.is_empty() {
                stdout.into_owned()
            } else {
                format!("{}{}", stdout, stderr)
            }
        }
        Err(e) => format!("Error: {}", e),
    }
}

fn execute_with_isolation(cmd: &str) -> String {
    if Command::new("bwrap").arg("--help").output().is_err() {
        return "bubblewrap installation not found. Please make sure you have `bwrap` on your path, or supply --no-isolation to disable safe-mode".to_string();
    }
    execute_direct(&format!("bwrap bash -c '{}'", cmd.replace("'", "'\\''")))
}

fn load_history() -> Result<Vec<String>> {
    let config_dir = config_dir().ok_or_else(|| anyhow::anyhow!("No config dir"))?;
    let history_path = config_dir.join("pipr").join("history");

    if history_path.exists() {
        let content = fs::read_to_string(history_path)?;
        Ok(content.split("---\n").map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect())
    } else {
        Ok(Vec::new())
    }
}

fn save_history(history: &[String]) -> Result<()> {
    let config_dir = config_dir().ok_or_else(|| anyhow::anyhow!("No config dir"))?;
    let pipr_dir = config_dir.join("pipr");
    fs::create_dir_all(&pipr_dir)?;

    let history_path = pipr_dir.join("history");
    let content = history.join("---\n");
    fs::write(history_path, content)?;
    Ok(())
}

fn print_config_reference() {
    let config = r#"
#  ____  _
# |  _ \(_)_ __  _ __       .________.
# | |_) | | '_ \| '__|      |________|
# |  __/| | |_) | |          |_    -|
# |_|   |_| .__/|_|     xX  xXx___x_|
#         |_|
#
# A commandline utility by
# Leon Kowarschick

# finish_hook: Executed once you close pipr, getting the command you constructed piped into stdin.
# finish_hook = "xclip -selection clipboard -in"

# Paranoid history mode writes every sucessfully running command into the history in autoeval mode.
paranoid_history_mode_default = false

autoeval_mode_default = true

history_size = 500
cmdlist_always_show_preview = false
cmd_timeout_millis = 2000

highlighting_enabled = true

eval_environment = ["bash", "-c"]

# Snippets can be used to quickly insert common bits of shell
# use || (two pipes) where you want your cursor to be after insertion
[snippets]
s = " | sed -r 's/||//g'"

[help_viewers]
'm' = "man ??"
'h' = "?? --help | less"

[output_viewers]
'l' = "less"
"#;
    println!("{}", config);
}

fn ui<B: Backend>(f: &mut Frame<B>, state: &AppState) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .margin(1)
        .constraints([
            Constraint::Length(3),
            Constraint::Min(5),
        ])
        .split(f.size());

    let autoeval_text = if state.autoeval { "[Autoeval]" } else { "" };
    let input_block = Block::default()
        .title(format!(" Command {} ", autoeval_text))
        .borders(Borders::ALL);

    let input_widget = Paragraph::new(state.command_input.as_str())
        .block(input_block)
        .wrap(Wrap { trim: true });

    f.render_widget(input_widget, chunks[0]);

    let output_block = Block::default()
        .title(" Output ")
        .borders(Borders::ALL);

    let output_widget = Paragraph::new(state.output.as_str())
        .block(output_block)
        .wrap(Wrap { trim: true });

    f.render_widget(output_widget, chunks[1]);

    if state.show_help {
        show_help_popup(f);
    }
}

fn show_help_popup<B: Backend>(f: &mut Frame<B>) {
    let help_text = r#"F1         Show/hide help
F2         Toggle autoeval
F3         Toggle Paranoid history (fills up history in autoeval)
F4         Show/hide history
Ctrl+B     Show/hide bookmarks
F5         Open helpviewer
F6         Open outputviewer
F7         When the cursor is on a `|` symbol, cache the output of everything
Ctrl+S     Save bookmark
Alt+Return Newline
Ctrl+U     Clear Command
Ctrl+P     Previous in history
Ctrl+N     Next in history
Ctrl+V     Insert snippet (press corresponding key to choose)

disable a line by starting it with a #
this will simply exclude the line from the executed command.

Config file is in
~/.config/pipr/pipr.toml"#;

    let popup = Block::default()
        .title(" Help ")
        .borders(Borders::ALL);

    let widget = Paragraph::new(help_text)
        .block(popup)
        .wrap(Wrap { trim: true });

    let popup_area = ratatui::layout::Rect {
        x: 5,
        y: 2,
        width: 80,
        height: 20,
    };

    f.render_widget(widget, popup_area);
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    if args.config_reference {
        print_config_reference();
        return Ok(());
    }

    // Setup terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // Initial draw
    let mut state = AppState::new(args.no_isolation);
    if let Some(default) = args.default {
        state.command_input = default;
        state.cursor_pos = state.command_input.len();
        state.execute_command();
    }

    if let Some(in_file) = args.in_file {
        if let Ok(content) = fs::read_to_string(in_file) {
            state.command_input = content;
            state.cursor_pos = state.command_input.len();
            state.execute_command();
        }
    }

    terminal.draw(|f| ui(f, &state))?;

    // Main loop
    loop {
        use crossterm::event::{self, Event, KeyCode, KeyEvent, KeyModifiers};

        if event::poll(std::time::Duration::from_millis(200))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        break;
                    }
                    KeyCode::Char(c) => {
                        state.handle_char(c);
                    }
                    KeyCode::Backspace => {
                        state.backspace();
                    }
                    KeyCode::Enter => {
                        state.execute_command();
                    }
                    KeyCode::F(1) => {
                        state.show_help = !state.show_help;
                    }
                    KeyCode::F(2) => {
                        state.autoeval = !state.autoeval;
                    }
                    KeyCode::F(3) => {
                        state.paranoid_history = !state.paranoid_history;
                    }
                    KeyCode::F(4) => {
                        state.show_history = !state.show_history;
                    }
                    KeyCode::F(5) => {
                        // Open help viewer - not implemented
                    }
                    KeyCode::F(6) => {
                        // Open output viewer - not implemented
                    }
                    KeyCode::F(7) => {
                        // Toggle output caching - not implemented
                    }
                    KeyCode::Char('p') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        state.prev_history();
                    }
                    KeyCode::Char('n') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        state.next_history();
                    }
                    KeyCode::Char('s') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        // Bookmark - not fully implemented
                    }
                    KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        state.command_input.clear();
                        state.cursor_pos = 0;
                    }
                    KeyCode::Char('v') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        // Snippet menu - not implemented
                    }
                    _ => {}
                }
            }
        }

        terminal.draw(|f| ui(f, &state))?;
    }

    // Restore terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Some(out_file) = args.out_file {
        let final_cmd = if args.raw_mode {
            state.command_input
        } else {
            state.command_input.lines().collect::<Vec<_>>().join(" ")
        };
        fs::write(out_file, final_cmd)?;
    }

    Ok(())
}
